config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":false,"bodySha256":"5dd11229da5be7e0440fccd07698260e8cc187055d586b082017b589bbc5fd2c","definitionSha256":"2ecc81cd3dee0304116755eb9027c1088be76d8c85a8b1eadf8c67fdef682a4a","volatility":"v","defaultExpressions":""},{"name":"own_imputation_command_capacity_core_v2","signature":"public.own_imputation_command_capacity_core_v2(jsonb,jsonb,uuid,integer)","argNames":["p","body_value","key","maximum_bytes"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":false,"bodySha256":"4da3da13d34a15a3cf268344800166e6bdf51da5e37cacf0b7c3b26750857d55","definitionSha256":"7bbc4ae2893be4834f0fdab689be3b0673e851987d82923e10f7338466fc7a93","volatility":"v","defaultExpressions":""},{"name":"own_imputation_source_full_v1","signature":"public.own_imputation_source_full_v1(jsonb,uuid,text)","argNames":["p","gid","fy"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"62b8da5b0664cdba3870cfaeccbc50ad1c7719046af9c32246fc97edc2a9cacb","definitionSha256":"e02320286281270a65b572f8b91619825da23fa69cb39fc4b19c4172ade229c5","volatility":"v","defaultExpressions":""},{"name":"own_imputation_detail_full_v1","signature":"public.own_imputation_detail_full_v1(jsonb,uuid)","argNames":["p","pid"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"0d5bd247201a808668be817962521cec714e1840121ea87a4a5225db9da2be81","definitionSha256":"28d23d575cb418ffa21d665dbf20771a4858d4c5b5b7624b45722b1c56eebee0","volatility":"v","defaultExpressions":""},{"name":"own_imputation_command_full_v1","signature":"public.own_imputation_command_full_v1(jsonb,jsonb,uuid)","argNames":["p","body_value","key"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"bodySha256":"71fe2080017eb037bf554d1212b0ae8ff1e3b8849c8ecd058b6d937ad40cd1cd","definitionSha256":"e2e2538fb84eb34c54fe8f0d5c1168958d36b62ebff7d2b2e063ba9817ac4a34","volatility":"v","defaultExpressions":""}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF actual.oid IS NULL OR actual.proowner<>current_user::regrole OR actual.prokind<>'f' OR NOT actual.prosecdef OR actual.proisstrict OR actual.proretset OR actual.proleakproof OR actual.proparallel<>'u'
   OR actual.provolatile IS DISTINCT FROM(expected->>'volatility')::"char" OR actual.procost<>100 OR actual.prorows<>0 OR actual.prosupport<>0 OR actual.probin IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.provariadic<>0 OR actual.prosqlbody IS NOT NULL
   OR actual.prorettype IS DISTINCT FROM to_regtype(expected->>'result') OR actual.prolang IS DISTINCT FROM(SELECT oid FROM pg_language WHERE lanname=expected->>'language') OR actual.pronargdefaults<>(expected->>'defaults')::integer OR actual.proargmodes IS NOT NULL
   OR coalesce(pg_get_expr(actual.proargdefaults,0),'') IS DISTINCT FROM expected->>'defaultExpressions'
   OR coalesce(to_jsonb(actual.proargnames),'null'::jsonb) IS DISTINCT FROM expected->'argNames' OR to_jsonb(actual.proconfig) IS DISTINCT FROM expected->'config'
   OR encode(sha256(convert_to(replace(actual.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')<>expected->>'bodySha256'
   OR(SELECT count(*) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=expected->>'name')<>1
  THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_SOURCE_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR(a.grantee<>actual.proowner AND NOT((expected->>'runtime')::boolean AND a.grantee=runtime_oid)))
   OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(expected->>'runtime')::boolean IS DISTINCT FROM EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=runtime_oid AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(SELECT count(*) FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))))<>(CASE WHEN(expected->>'runtime')::boolean THEN 2 ELSE 1 END)
  THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_ACL_CHANGED';END IF;
  original_functions:=original_functions||jsonb_build_array(to_jsonb(actual));
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_source_capacity_core_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_detail_capacity_core_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_command_capacity_core_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_source_full_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_detail_full_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='own_journal_command_full_v1') THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 IF(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_journal_%')<>13 OR(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_imputation_%')<>17 THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 target_relation:=to_regclass('public.own_payroll_journal_event');
 IF target_relation IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class t WHERE t.oid=target_relation AND t.relowner=current_user::regrole AND t.relkind='r' AND t.relrowsecurity AND NOT t.relforcerowsecurity AND t.relpersistence='p') OR EXISTS(SELECT 1 FROM pg_class t CROSS JOIN LATERAL aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) a WHERE t.oid=target_relation AND a.grantee<>t.relowner) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=target_relation) THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_TABLE_CHANGED';END IF;
 LOCK TABLE public.own_payroll_journal_event IN ACCESS EXCLUSIVE MODE NOWAIT;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_source_snapshot_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(source_snapshot) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((source_snapshot)::text) <= 16777216))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_journal_snapshot_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(journal_snapshot) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((journal_snapshot)::text) <= 16777216))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_body_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(body) = ''object''::text) AND (octet_length((body)::text) <= 8388608))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT to_jsonb(t) INTO table_before FROM pg_class t WHERE t.oid=target_relation;
 SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]') INTO constraints_before FROM pg_constraint c WHERE c.conrelid=target_relation AND c.conname NOT IN('own_payroll_journal_event_source_snapshot_check','own_payroll_journal_event_journal_snapshot_check');
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attnum),'[]') INTO columns_before FROM pg_attribute a WHERE a.attrelid=target_relation;
 SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]') INTO indexes_before FROM pg_index i WHERE i.indrelid=target_relation;
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]') INTO triggers_before FROM pg_trigger t WHERE t.tgrelid=target_relation;
 ALTER TABLE public.own_payroll_journal_event
  DROP CONSTRAINT own_payroll_journal_event_source_snapshot_check,
  ADD CONSTRAINT own_payroll_journal_event_source_snapshot_check CHECK(jsonb_typeof(source_snapshot) IN('object','null') AND octet_length(source_snapshot::text)<=33554432),
  DROP CONSTRAINT own_payroll_journal_event_journal_snapshot_check,
  ADD CONSTRAINT own_payroll_journal_event_journal_snapshot_check CHECK(jsonb_typeof(journal_snapshot) IN('object','null') AND octet_length(journal_snapshot::text)<=33554432);
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_source_capacity_core_v1(p jsonb,basis_value text,id_value uuid,maximum_bytes integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;d jsonb;s jsonb;h jsonb;
BEGIN
 IF maximum_bytes IS NULL OR maximum_bytes NOT IN(16777216,33554432) THEN RAISE EXCEPTION 'JOURNAL_INPUT_INVALID';END IF;
 ctx:=public.own_run_context_v1(p,true,false);PERFORM public.own_journal_lock_v1(ctx);
 IF basis_value='imputation' THEN
  IF maximum_bytes=33554432 THEN d:=public.own_imputation_detail_full_v1(p,id_value);ELSE d:=public.own_imputation_detail_v1(p,id_value);END IF;IF d#>>'{proposal,status}' IS DISTINCT FROM 'approved' OR d->'sourceCurrent' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'JOURNAL_SOURCE_CHANGED';END IF;
  h:=jsonb_build_object('version','own-payroll-journal-source.v1','basis',basis_value,'imputationId',d#>>'{proposal,id}','requestSha256',d#>>'{proposal,requestSha256}','decision',d#>'{proposal,decision}','allocationSha256',d->>'allocationSha256','snapshotSha256',d#>>'{allocation,snapshotSha256}');
  s:=jsonb_build_object('imputation',d,'original',NULL);
 ELSIF basis_value='journal' THEN
  d:=public.own_journal_detail_capacity_core_v1(p,id_value,maximum_bytes);IF d->>'status' IS DISTINCT FROM 'posted' OR d->>'kind' IS DISTINCT FROM 'initial' THEN RAISE EXCEPTION 'JOURNAL_DECIDED';END IF;
  h:=jsonb_build_object('version','own-payroll-journal-source.v1','basis',basis_value,'originalId',d->>'id','journalSha256',d->>'journalSha256','stateVersion',d->>'stateVersion','number',d->'number','postingDate',d->>'postingDate');s:=jsonb_build_object('imputation',NULL,'original',d);
 ELSE RAISE EXCEPTION 'JOURNAL_INPUT_INVALID';END IF;
 s:=s||jsonb_build_object('version','own-payroll-journal-source.v1','scopeVersion',public.native_salary_scope_v1(ctx),'basis',basis_value,'sourceVersion',public.own_run_hash_v1(h),'complete',true);
 IF maximum_bytes=33554432 AND octet_length(s::text)+19>maximum_bytes THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;RETURN s;
END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_detail_capacity_core_v1(p jsonb,id_value uuid,maximum_bytes integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;e public.own_payroll_journal_event;found_value public.own_payroll_journal_event;summary jsonb;current_source jsonb;current_value boolean:=false;d jsonb;h jsonb;BEGIN
 IF maximum_bytes IS NULL OR maximum_bytes NOT IN(16777216,33554432) THEN RAISE EXCEPTION 'JOURNAL_INPUT_INVALID';END IF;
 ctx:=public.own_run_context_v1(p,true,false);PERFORM public.own_journal_lock_v1(ctx);
 SELECT * INTO found_value FROM public.own_payroll_journal_event WHERE id=id_value AND tenant_id=(ctx->>'tenantId')::uuid AND source_binding_id=(ctx->>'sourceBindingId')::uuid;
 IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_NOT_FOUND';END IF;
 SELECT * INTO e FROM public.own_payroll_journal_event WHERE id=coalesce(found_value.proposal_id,found_value.id) AND command='propose';
 summary:=public.own_journal_summary_v1(ctx,e);
 BEGIN
  IF e.basis='imputation' THEN current_source:=public.own_journal_source_capacity_core_v1(p,'imputation',(e.body->>'sourceId')::uuid,maximum_bytes);current_value:=current_source->>'sourceVersion'=e.body->>'sourceVersion';
  ELSIF summary->>'status'='posted' THEN SELECT id INTO found_value.id FROM public.own_payroll_journal_event WHERE original_id=e.original_id AND basis='journal' AND command='post';current_value:=found_value.id::text=summary->>'id';
  ELSE current_source:=public.own_journal_source_capacity_core_v1(p,'journal',e.original_id,maximum_bytes);current_value:=current_source->>'sourceVersion'=e.body->>'sourceVersion';END IF;
 EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT IN('JOURNAL_SOURCE_CHANGED','JOURNAL_DECIDED') THEN RAISE;END IF;END;
 IF maximum_bytes=33554432 AND octet_length(e.source_snapshot::text)+octet_length(e.journal_snapshot::text)+octet_length(e.body::text)+16384>maximum_bytes THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;
 d:=jsonb_build_object('version','own-payroll-journal.v1','id',summary->'id','proposalId',e.id,'body',e.body,'requestSha256',e.request_sha256,'source',e.source_snapshot,'journal',e.journal_snapshot,'journalSha256',e.body->>'journalSha256','status',summary->>'status','kind',e.journal_snapshot->>'kind','postingDate',e.body->>'postingDate','number',summary->'number','sourceCurrent',current_value,'canReview',summary->'canReview','authorLabel',e.actor_label,'decision',summary->'decision','reversedBy',summary->'reversedBy');
 h:=jsonb_build_object('version','own-payroll-journal.v1','id',d->'id','proposalId',d->'proposalId','requestSha256',d->'requestSha256','journalSha256',d->'journalSha256','status',d->'status','number',d->'number','decision',d->'decision','reversedBy',d->'reversedBy');
 d:=d||jsonb_build_object('stateVersion',public.own_run_hash_v1(h));IF octet_length(d::text)+(CASE WHEN maximum_bytes=33554432 THEN 19 ELSE 0 END)>maximum_bytes THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;RETURN d;
END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_command_capacity_core_v1(p jsonb,body_value jsonb,key uuid,maximum_bytes integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;cmd text;basis_value text;eid uuid:=gen_random_uuid();pid uuid;original_value uuid;gid uuid;period_value text;type_value text;fy text;num integer;fingerprint text;source_value jsonb;journal_value jsonb;captured_source jsonb;captured_journal jsonb;proposal public.own_payroll_journal_event;prior public.own_payroll_journal_event;receipt_value jsonb;added bigint;detail_value jsonb;BEGIN
 IF maximum_bytes IS NULL OR maximum_bytes NOT IN(16777216,33554432) THEN RAISE EXCEPTION 'JOURNAL_INPUT_INVALID';END IF;
 ctx:=public.own_run_context_v1(p,true,false);PERFORM public.own_journal_command_body_v1(body_value);cmd:=body_value->>'command';basis_value:=body_value->>'basis';
 IF key IS NULL OR key::text!~'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' OR octet_length(body_value::text)>8388608 THEN RAISE EXCEPTION 'JOURNAL_INPUT_INVALID';END IF;
 IF NOT public.action_center_context_has_capability(ctx,CASE cmd WHEN 'propose' THEN 'payroll.parameter.prepare' ELSE 'payroll.parameter.approve' END) THEN RAISE EXCEPTION 'JOURNAL_FORBIDDEN';END IF;
 PERFORM public.own_journal_lock_v1(ctx);fingerprint:=public.own_run_hash_v1(body_value);
 SELECT * INTO prior FROM public.own_payroll_journal_event WHERE tenant_id=(ctx->>'tenantId')::uuid AND source_binding_id=(ctx->>'sourceBindingId')::uuid AND actor_membership_id=(ctx->>'membershipId')::uuid AND request_key=key;
 IF FOUND THEN IF prior.request_sha256<>fingerprint OR prior.body<>body_value THEN RAISE EXCEPTION 'JOURNAL_IDEMPOTENCY_REUSE';END IF;RETURN public.own_journal_attempt_v1(p,key);END IF;
 IF body_value->>'scopeVersion' IS DISTINCT FROM public.native_salary_scope_v1(ctx) THEN RAISE EXCEPTION 'JOURNAL_SCOPE_CHANGED';END IF;
 IF cmd='propose' THEN
  pid:=eid;source_value:=public.own_journal_source_capacity_core_v1(p,basis_value,(body_value->>'sourceId')::uuid,maximum_bytes);journal_value:=public.own_journal_calculate_v1(source_value,body_value->>'postingDate',body_value->'rules');
  IF source_value->>'sourceVersion' IS DISTINCT FROM body_value->>'sourceVersion' OR public.own_run_hash_v1(journal_value) IS DISTINCT FROM body_value->>'journalSha256' THEN RAISE EXCEPTION 'JOURNAL_SOURCE_CHANGED';END IF;
  IF basis_value='imputation' AND public.own_journal_duplicate_v1(ctx,source_value,NULL) THEN RAISE EXCEPTION 'JOURNAL_DUPLICATE';END IF;
  IF basis_value='journal' AND EXISTS(SELECT 1 FROM public.own_payroll_journal_event e LEFT JOIN public.own_payroll_journal_event d ON d.proposal_id=e.id WHERE e.tenant_id=(ctx->>'tenantId')::uuid AND e.source_binding_id=(ctx->>'sourceBindingId')::uuid AND e.command='propose' AND e.basis='journal' AND e.original_id=(body_value->>'sourceId')::uuid AND (d.id IS NULL OR d.command='post')) THEN RAISE EXCEPTION 'JOURNAL_DUPLICATE';END IF;
 ELSE
  pid:=(body_value->>'proposalId')::uuid;SELECT * INTO proposal FROM public.own_payroll_journal_event WHERE id=pid AND command='propose' AND tenant_id=(ctx->>'tenantId')::uuid AND source_binding_id=(ctx->>'sourceBindingId')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_NOT_FOUND';END IF;
  IF EXISTS(SELECT 1 FROM public.own_payroll_journal_event WHERE proposal_id=pid) THEN RAISE EXCEPTION 'JOURNAL_DECIDED';END IF;
  IF NOT(public.own_journal_summary_v1(ctx,proposal)->>'canReview')::boolean THEN RAISE EXCEPTION 'JOURNAL_INDEPENDENT_REQUIRED';END IF;
  IF body_value->>'proposalSha256' IS DISTINCT FROM proposal.request_sha256 OR body_value-ARRAY['command','scopeVersion','proposalId','proposalSha256','reason'] IS DISTINCT FROM proposal.body-ARRAY['command','scopeVersion','proposalId','proposalSha256','reason'] THEN RAISE EXCEPTION 'JOURNAL_PROPOSAL_CHANGED';END IF;
  source_value:=proposal.source_snapshot;journal_value:=proposal.journal_snapshot;
  IF cmd='post' THEN
   captured_source:=public.own_journal_source_capacity_core_v1(p,basis_value,(body_value->>'sourceId')::uuid,maximum_bytes);captured_journal:=public.own_journal_calculate_v1(captured_source,body_value->>'postingDate',body_value->'rules');
   IF captured_source->>'sourceVersion' IS DISTINCT FROM body_value->>'sourceVersion' OR captured_journal IS DISTINCT FROM journal_value OR public.own_run_hash_v1(captured_journal) IS DISTINCT FROM body_value->>'journalSha256' THEN RAISE EXCEPTION 'JOURNAL_SOURCE_CHANGED';END IF;
   IF basis_value='imputation' AND public.own_journal_duplicate_v1(ctx,captured_source,pid) THEN RAISE EXCEPTION 'JOURNAL_DUPLICATE';END IF;
  END IF;
 END IF;
 gid:=(journal_value->>'groupId')::uuid;original_value:=(journal_value->>'originalId')::uuid;period_value:=journal_value->>'period';type_value:=journal_value->>'liquidationType';fy:=journal_value->>'fiscalYear';
 IF cmd='post' THEN SELECT coalesce(max(entry_number),0)+1 INTO num FROM public.own_payroll_journal_event WHERE tenant_id=(ctx->>'tenantId')::uuid AND source_binding_id=(ctx->>'sourceBindingId')::uuid AND fiscal_year=fy;END IF;
 IF cmd='propose' AND(SELECT count(*) FROM public.own_payroll_journal_event WHERE tenant_id=(ctx->>'tenantId')::uuid AND source_binding_id=(ctx->>'sourceBindingId')::uuid AND command='propose')>=1000 THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('own-journal:capacity:v1',0)) THEN RAISE EXCEPTION 'JOURNAL_BUSY';END IF;
 IF cmd<>'propose' THEN source_value:='null';journal_value:='null';END IF;
 added:=octet_length(source_value::text)+octet_length(journal_value::text)+4*octet_length(body_value::text)+8192;
 IF octet_length(source_value::text)+octet_length(journal_value::text)+octet_length(body_value::text)+(CASE WHEN maximum_bytes=33554432 THEN 16384 ELSE 8192 END)>maximum_bytes OR(SELECT coalesce(sum(octet_length(e.body::text)+octet_length(e.source_snapshot::text)+octet_length(e.journal_snapshot::text)+octet_length(e.receipt::text)),0) FROM public.own_payroll_journal_event e)+added>536870912 OR(SELECT coalesce(sum(octet_length(e.body::text)+octet_length(e.source_snapshot::text)+octet_length(e.journal_snapshot::text)+octet_length(e.receipt::text)),0) FROM public.own_payroll_journal_event e WHERE e.tenant_id=(ctx->>'tenantId')::uuid AND e.source_binding_id=(ctx->>'sourceBindingId')::uuid)+added>268435456 THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;
 receipt_value:=jsonb_build_object('version','own-payroll-journal.v1','eventId',eid,'proposalId',pid,'requestKey',key,'requestSha256',fingerprint,'body',body_value,'status',CASE cmd WHEN 'propose' THEN 'pending' WHEN 'post' THEN 'posted' ELSE 'rejected' END,'number',num,'journalSha256',body_value->>'journalSha256','sourceVersion',body_value->>'sourceVersion','replayed',false,'accountingPosted',cmd='post','paymentExecuted',false);
 INSERT INTO public.own_payroll_journal_event(id,tenant_id,source_binding_id,proposal_id,original_id,group_id,period,liquidation_type,fiscal_year,entry_number,command,basis,body,source_snapshot,journal_snapshot,actor_membership_id,actor_person_id,actor_email,actor_session_id,actor_session_version,release_sha,actor_label,request_key,request_sha256,receipt)
 VALUES(eid,(ctx->>'tenantId')::uuid,(ctx->>'sourceBindingId')::uuid,CASE WHEN cmd='propose' THEN NULL ELSE pid END,original_value,gid,period_value,type_value,fy,num,cmd,basis_value,body_value,source_value,journal_value,(ctx->>'membershipId')::uuid,(ctx->>'actorPersonId')::uuid,ctx->>'actorEmail',(p->>'actorSessionId')::uuid,(p->>'actorSessionVersion')::integer,p->>'releaseSha',ctx->>'actorLabel',key,fingerprint,receipt_value);
 -- Full proposals must have a complete readable detail before return.
 -- No exception handler absorbs this guard: failure aborts the preceding INSERT.
 -- A posted historical original is valid for reversal; only the NEW proposal
 -- must still describe the source revalidated by the original command logic.
 IF maximum_bytes=33554432 AND cmd='propose' THEN
  detail_value:=public.own_journal_detail_capacity_core_v1(p,pid,maximum_bytes);
  IF detail_value->'sourceCurrent' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'JOURNAL_SOURCE_CHANGED';END IF;
 END IF;
 RETURN receipt_value;
END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE OR REPLACE FUNCTION public.own_journal_source_value_v1(p jsonb,basis_value text,id_value uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
BEGIN RETURN public.own_journal_source_capacity_core_v1(p,basis_value,id_value,16777216);END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE OR REPLACE FUNCTION public.own_journal_detail_v1(p jsonb,id_value uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
BEGIN RETURN public.own_journal_detail_capacity_core_v1(p,id_value,16777216);END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE OR REPLACE FUNCTION public.own_journal_command_v1(p jsonb,body_value jsonb,key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
BEGIN RETURN public.own_journal_command_capacity_core_v1(p,body_value,key,16777216);END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_source_full_v1(p jsonb,basis_value text,id_value uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE s jsonb;BEGIN s:=public.own_journal_source_capacity_core_v1(p,basis_value,id_value,33554432);IF octet_length(s::text)+19>33554432 THEN RAISE EXCEPTION 'JOURNAL_LIMIT';END IF;RETURN s;END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_detail_full_v1(p jsonb,id_value uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
BEGIN RETURN public.own_journal_detail_capacity_core_v1(p,id_value,33554432);END $$;$journal_capacity_definition$;
 EXECUTE $journal_capacity_definition$CREATE FUNCTION public.own_journal_command_full_v1(p jsonb,body_value jsonb,key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $$
BEGIN RETURN public.own_journal_command_capacity_core_v1(p,body_value,key,33554432);END $$;$journal_capacity_definition$;
