sql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":true,"volatility":"v","bodySha256":"f6b6f6a03f9020a6704b97fe7c81cbaa3095fa74fb40023ba5188a369159c07d","definitionSha256":"e9e1bef6e492ceb211bfc26d696eac48306c3cd45aadf755e73746829640f037"},{"name":"own_journal_detail_full_v1","signature":"public.own_journal_detail_full_v1(jsonb,uuid)","argNames":["p","id_value"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"volatility":"v","bodySha256":"69506aba24d5779f3493256a9c5f98423d799b057f587ea78535f6a67cd5027f","definitionSha256":"b694d3b95772c5241f826ca3908c4ef9a6b5bcdc67827e0ae00ecb8c447364ca"},{"name":"own_journal_command_full_v1","signature":"public.own_journal_command_full_v1(jsonb,jsonb,uuid)","argNames":["p","body_value","key"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"volatility":"v","bodySha256":"1e88e76ada3d19d795c6be83b2a8eae8b873a2f2fc7f9062f33a1ae681804571","definitionSha256":"955e2039dccc4c786832c335bb362078a66f37c605d6814cd19799a2867367a0"}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF actual.oid IS NULL OR actual.proowner<>current_user::regrole OR actual.prokind<>'f' OR NOT actual.prosecdef OR actual.proisstrict OR actual.proretset OR actual.proleakproof OR actual.proparallel<>'u'
   OR actual.provolatile IS DISTINCT FROM(expected->>'volatility')::"char" OR actual.procost<>100 OR actual.prorows<>0 OR actual.prosupport<>0 OR actual.probin IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.provariadic<>0 OR actual.prosqlbody IS NOT NULL
   OR actual.prorettype IS DISTINCT FROM to_regtype(expected->>'result') OR actual.prolang IS DISTINCT FROM(SELECT oid FROM pg_language WHERE lanname=expected->>'language') OR actual.pronargdefaults<>(expected->>'defaults')::integer OR actual.proargmodes IS NOT NULL
   OR coalesce(pg_get_expr(actual.proargdefaults,0),'') IS DISTINCT FROM expected->>'defaultExpressions'
   OR coalesce(to_jsonb(actual.proargnames),'null'::jsonb) IS DISTINCT FROM expected->'argNames' OR to_jsonb(actual.proconfig) IS DISTINCT FROM expected->'config'
   OR encode(sha256(convert_to(replace(actual.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')<>expected->>'bodySha256'
   OR(SELECT count(*) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=expected->>'name')<>1
  THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_SOURCE_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR(a.grantee<>actual.proowner AND NOT((expected->>'runtime')::boolean AND a.grantee=runtime_oid)))
   OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(expected->>'runtime')::boolean IS DISTINCT FROM EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=runtime_oid AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(SELECT count(*) FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))))<>(CASE WHEN(expected->>'runtime')::boolean THEN 2 ELSE 1 END)
  THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_ACL_CHANGED';END IF;
 END LOOP;
 FOR prior IN SELECT value FROM jsonb_array_elements(original_functions) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=(prior->>'oid')::oid;
  IF actual.oid IS NULL OR(actual.proname IN('own_journal_source_value_v1','own_journal_detail_v1','own_journal_command_v1') AND(to_jsonb(actual)-'prosrc') IS DISTINCT FROM(prior-'prosrc'))
   OR(actual.proname NOT IN('own_journal_source_value_v1','own_journal_detail_v1','own_journal_command_v1') AND to_jsonb(actual) IS DISTINCT FROM prior)
  THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_ORIGINAL_METADATA_CHANGED';END IF;
 END LOOP;
 IF(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_journal_%')<>19 OR(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_imputation_%')<>17 THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_OBJECT_CONFLICT';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_source_snapshot_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(source_snapshot) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((source_snapshot)::text) <= 33554432))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_journal_snapshot_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(journal_snapshot) = ANY (ARRAY[''object''::text, ''null''::text])) AND (octet_length((journal_snapshot)::text) <= 33554432))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT * INTO checked_constraint FROM pg_constraint WHERE conrelid=target_relation AND conname='own_payroll_journal_event_body_check';
 IF checked_constraint.oid IS NULL OR checked_constraint.contype<>'c' OR NOT checked_constraint.convalidated OR NOT checked_constraint.conislocal OR checked_constraint.coninhcount<>0 OR checked_constraint.connoinherit OR checked_constraint.condeferrable OR checked_constraint.condeferred
  OR pg_get_expr(checked_constraint.conbin,checked_constraint.conrelid,false) IS DISTINCT FROM '((jsonb_typeof(body) = ''object''::text) AND (octet_length((body)::text) <= 8388608))' THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_CHECK_CHANGED';END IF;
 SELECT to_jsonb(t) INTO table_after FROM pg_class t WHERE t.oid=target_relation;
 IF table_after IS DISTINCT FROM table_before
  OR columns_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.attnum),'[]') FROM pg_attribute a WHERE a.attrelid=target_relation)
  OR constraints_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]') FROM pg_constraint c WHERE c.conrelid=target_relation AND c.conname NOT IN('own_payroll_journal_event_source_snapshot_check','own_payroll_journal_event_journal_snapshot_check'))
  OR indexes_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]') FROM pg_index i WHERE i.indrelid=target_relation)
  OR triggers_before IS DISTINCT FROM(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]') FROM pg_trigger t WHERE t.tgrelid=target_relation)
 THEN RAISE EXCEPTION 'JOURNAL_CAPACITY_TABLE_METADATA_CHANGED';END IF;
END $journal_capacity_206$;
